public class CoffeeOrderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("SMALL price", 2.00, CoffeeOrder.Size.SMALL.getPrice());
        check("MEDIUM price", 2.75, CoffeeOrder.Size.MEDIUM.getPrice());
        check("LARGE price", 3.50, CoffeeOrder.Size.LARGE.getPrice());
        check("total of one of each", 8.25, CoffeeOrder.totalFor(
                new CoffeeOrder.Size[]{CoffeeOrder.Size.SMALL, CoffeeOrder.Size.MEDIUM, CoffeeOrder.Size.LARGE}));
        check("total of two LARGE", 7.00, CoffeeOrder.totalFor(
                new CoffeeOrder.Size[]{CoffeeOrder.Size.LARGE, CoffeeOrder.Size.LARGE}));
        check("total of empty order", 0.0, CoffeeOrder.totalFor(new CoffeeOrder.Size[0]));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
