public class CoffeeOrder {

    public enum Size {
        SMALL(2.00), MEDIUM(2.75), LARGE(3.50);

        private final double price;

        Size(double price) {
            this.price = price;
        }

        public double getPrice() {
            return price;
        }
    }

    public static double totalFor(Size[] order) {
        double total = 0.0;
        for (Size s : order) {
            total += s.getPrice();
        }
        return total;
    }
}
